package com.hotel.booking.service;
import com.hotel.booking.dao.RoomDAO;import com.hotel.booking.model.Room;import java.sql.SQLException;import java.math.BigDecimal;import java.util.List;
public class RoomService {private final RoomDAO dao=new RoomDAO();public Room add(String number,String type,BigDecimal price)throws SQLException{if(number==null||number.isBlank()||type==null||type.isBlank()||price==null||price.signum()<=0)throw new IllegalArgumentException("Room number, type and positive price are required.");return dao.add(new Room(number.trim(),type.trim(),price));}public List<Room> all()throws SQLException{return dao.all();}public List<Room> available()throws SQLException{return dao.available();}public boolean setStatus(int id,String status)throws SQLException{if(!status.equals("AVAILABLE")&&!status.equals("MAINTENANCE"))throw new IllegalArgumentException("Status must be AVAILABLE or MAINTENANCE.");return dao.setStatus(id,status);}public Room byId(int id)throws SQLException{return dao.byId(id);}}
